# ------------------------------------------------------------------ media gap report (findings, not swept under the rug)
# Wes's requirement: distinguish development availability from production readiness, and flag any preset whose
# production-ready pool goes thin as a result. These 8 have a local thumbnail file on disk (confirmed present) but
# `thumbnail_manifest.csv` carries no hosted `image_url` for them -- so despite the scope doc's "zero remaining
# images" note, they are NOT production-ready today. This contradicts that note; see the final report for the
# preset-level impact (Landmine Full Body loses all 4 of its curated combined-movement additions, which were its
# equipment-identity anchor for the default Complex/Flow flavor; Barbell Lower Body loses 3 of 5 curated additions
# but is not thin -- the frozen library's own barbell squat/deadlift work fills the gap).
MEDIA_GAPS = [r['name'] for r in SPECIALTY_EXERCISES.values() if r['media_status'] == 'dev_only']


def production_ready(ex_or_id):
    """True if a specialty-catalog record (dict) is eligible for production-mode generation."""
    rec = SPECIALTY_EXERCISES.get(ex_or_id) if isinstance(ex_or_id, str) else ex_or_id
    if rec is None: return True   # not a specialty-catalog item (frozen production exercise) -> always production ready
    return rec.get('media_status') == 'production_ready'
